00053 class EntropyModelResiduals {
00054     // State of the residual RLE modelling - used to select between 3 huffman trees
00055     enum State { STATE_LSB, STATE_MSB, STATE_ZERO, STATE_COUNT };
00056 
00057 public:
00058     EntropyModelResiduals() {}
00059 
00060     void encode_high_count(State state, unsigned symbol);
00061     void encode_run(int16_t residual, unsigned zeros);
00062     EncodedChunk finish();
00063 
00064 private:
00065     void encode_symbol(State state, unsigned symbol);
00066 
00067     HuffmanEncoderBuilder huffman_state_[STATE_COUNT];
00068 
00069     struct RleSymbol {
00070         RleSymbol() = default;
00071         RleSymbol(State st, uint8_t sy) : state(st), symbol(sy) {}
00072         State state = STATE_LSB;
00073         uint8_t symbol = 0;
00074     };
00075 
00076     std::vector<RleSymbol> rle_symbols_;
00077 };
00078 
00079 void EntropyModelResiduals::encode_symbol(State state, unsigned symbol) {
00080     rle_symbols_.emplace_back(state, symbol);
00081     huffman_state_[state].add_symbol(symbol, 1);
00082 }
00083 
00084 void EntropyModelResiduals::encode_high_count(State s, unsigned c) {
00085     if (c > 0x7f)
00086         encode_high_count(s, c >> 7);
00087     encode_symbol(s, (c & 0x7f) | 0x80);
00088 }
00089 
00090 void EntropyModelResiduals::encode_run(int16_t residual, unsigned zeros) {
00091     // Is there a run?
00092     const uint16_t zeros_bit = (zeros > 0) ? 0x80 : 0;
00093 
00094     // Encode value
00095     if (residual >= -32 && residual < 32) {
00096         encode_symbol(STATE_LSB, (residual * 2 + 0x40) | zeros_bit);
00097     } else {
00098         const uint16_t clamped_residual = std::min(std::max(residual + 0x2000, 0), 0x3fff) << 1;
00099         encode_symbol(STATE_LSB, (clamped_residual & 0xfe) | 0x01);
00100         encode_symbol(STATE_MSB, ((clamped_residual >> 8) & 0x7f) | zeros_bit);
00101     }
00102 
00103     // Add any required run symbols
00104     // LSByte first
00105     /***
00106     while (zeros) {
00107         const uint8_t low_bits = zeros & 0x7f;
00108         zeros >>= 7;
00109 
00110         if (zeros)
00111             encode_symbol(STATE_ZERO, low_bits | 0x80);
00112         else
00113             encode_symbol(STATE_ZERO, low_bits);
00114     }
00115     ***/
00116     // MSByte first
00117     /***/
00118     if (zeros_bit) {
00119         if (zeros > 0x7f)
00120             encode_high_count(STATE_ZERO, zeros >> 7);
00121         encode_symbol(STATE_ZERO, zeros & 0x7f);
00122     }
00123     /***/
00124 }
00125 
00126 EncodedChunk EntropyModelResiduals::finish() {
00127     // Generate huffman encoders
00128     std::vector<HuffmanEncoder> huffman_encoders;
00129 
00130     BitstreamPacker raw_packer;
00131     BitstreamPacker huffman_packer;
00132 
00133     // Finialise huffman encoders state
00134     for (unsigned h = 0; h < STATE_COUNT; ++h) {
00135         huffman_encoders.emplace_back(huffman_state_[h].finish());
00136         huffman_encoders.back().write_codes(huffman_packer);
00137     }
00138 
00139     // Code symbols both ways: raw vs. prefix
00140     for (const auto s : rle_symbols_) {
00141         raw_packer.u(8, s.symbol);
00142         huffman_encoders[s.state].write_symbol(huffman_packer, s.symbol);
00143     }
00144 
00145     return EncodedChunk(raw_packer.finish(), huffman_packer.finish());
00146 }
00147 
00148 EncodedChunk EntropyEncoderResiduals::process(const Surface &surface) {
00149     auto view = surface.view_as<int16_t>();
00150     const unsigned width = view.width();
00151     const unsigned height = view.height();
00152 
00153     EntropyModelResiduals models;
00154 
00155     int16_t residual = 0;
00156     unsigned zeros = 0;
00157 
00158     bool has_entropy = false;
00159 
00160     for (unsigned y = 0; y < height; ++y) {
00161         for (unsigned x = 0; x < width; ++x) {
00162 
00163             int16_t r = view.read(x, y);
00164 
00165             // Record if there is any data in surface
00166             if (r)
00167                 has_entropy = true;
00168 
00169             // Special case - always have to encode first symbol, even if it is zero
00170             if (x == 0 && y == 0) {
00171                 residual = r;
00172                 zeros = 0;
00173                 continue;
00174             }
00175 
00176             if (r == 0) {
00177                 // Extend current run
00178                 zeros++;
00179             } else {
00180                 // Emit previous run and record this residual
00181                 models.encode_run(residual, zeros);
00182                 residual = r;
00183                 zeros = 0;
00184             }
00185         }
00186     }
00187 
00188     // Emit last run
00189     models.encode_run(residual, zeros);
00190 
00191     if (has_entropy)
00192         return models.finish();
00193     else
00194         return EncodedChunk();
00195 }
00196 
00197 EncodedChunk EntropyEncoderResidualsTiled::process(const Surface &surface, unsigned transform_block_size) {
00198     auto view = surface.view_as<int16_t>();
00199     const unsigned width = view.width();
00200     const unsigned height = view.height();
00201 
00202     // Divisor for block->tiles
00203     const unsigned d = 32 / transform_block_size;
00204 
00205     EntropyModelResiduals models;
00206 
00207     int16_t residual = 0;
00208     unsigned zeros = 0;
00209 
00210     bool has_entropy = false;
00211 
00212     for (unsigned ty = 0; ty < height; ty += d) {
00213         for (unsigned tx = 0; tx < width; tx += d) {
00214 
00215             // For each transform in tile ...
00216             for (unsigned y = ty; y < std::min(ty + d, height); ++y) {
00217                 for (unsigned x = tx; x < std::min(tx + d, width); ++x) {
00218                     int16_t r = view.read(x, y);
00219 
00220                     // Record if there is any data in surface
00221                     if (r)
00222                         has_entropy = true;
00223 
00224                     // Special case - always have to encode first symbol, even if it is zero
00225                     if (x == 0 && y == 0) {
00226                         residual = r;
00227                         zeros = 0;
00228                         continue;
00229                     }
00230 
00231                     if (r == 0) {
00232                         // Extend current run
00233                         zeros++;
00234                     } else {
00235                         // Emit previous run and record this residual
00236                         models.encode_run(residual, zeros);
00237                         residual = r;
00238                         zeros = 0;
00239                     }
00240                 }
00241             }
00242         }
00243     }
00244 
00245     // Emit last run
00246     models.encode_run(residual, zeros);
00247 
00248     if (has_entropy)
00249         return models.finish();
00250     else
00251         return EncodedChunk();
00252 }
