00258 //
00259 // Encode a mask of 0,1 runs using two models
00260 //
00261 class EntropyModelRleFlag {
00262     // State of the RLE parser - used to select between 2 huffman trees (0.., 1..)
00263     enum State { STATE_ZERO_RUN, STATE_ONE_RUN, STATE_COUNT };
00264 
00265 public:
00266     EntropyModelRleFlag() {}
00267 
00268     void encode_high_count(State s, unsigned c);
00269     void encode_run(bool value, unsigned count);
00270     EncodedChunk finish(bool start_value);
00271 
00272 private:
00273     void encode_symbol(State state, unsigned symbol);
00274 
00275     HuffmanEncoderBuilder huffman_state_[STATE_COUNT];
00276 
00277     struct RleSymbol {
00278         RleSymbol() = default;
00279         RleSymbol(State st, uint8_t sy) : state(st), symbol(sy) {}
00280         State state = STATE_ZERO_RUN;
00281         uint8_t symbol = 0;
00282     };
00283 
00284     std::vector<RleSymbol> rle_symbols_;
00285 };
00286 
00287 void EntropyModelRleFlag::encode_symbol(State state, unsigned symbol) {
00288     rle_symbols_.emplace_back(state, symbol);
00289     huffman_state_[state].add_symbol(symbol, 1);
00290 }
00291 
00292 void EntropyModelRleFlag::encode_high_count(State s, unsigned c) {
00293     if (c > 0x7f)
00294         encode_high_count(s, c >> 7);
00295     encode_symbol(s, (c & 0x7f) | 0x80);
00296 }
00297 
00298 void EntropyModelRleFlag::encode_run(bool value, unsigned count) {
00299 
00300     const State s = value ? STATE_ONE_RUN : STATE_ZERO_RUN;
00301 
00302     if (count > 0x7f)
00303         encode_high_count(s, count >> 7);
00304     encode_symbol(s, count & 0x7f);
00305 }
00306 
00307 EncodedChunk EntropyModelRleFlag::finish(bool start_value) {
00308 
00309     // Generate huffman encoders
00310     std::vector<HuffmanEncoder> huffman_encoders;
00311 
00312     BitstreamPacker raw_packer;
00313     BitstreamPacker huffman_packer;
00314 
00315     // Finialise huffman encoders state
00316     for (unsigned h = 0; h < STATE_COUNT; ++h) {
00317         huffman_encoders.emplace_back(huffman_state_[h].finish());
00318         huffman_encoders.back().write_codes(huffman_packer);
00319     }
00320 
00321     // Add starting value to each bitstream
00322     raw_packer.u(8, start_value ? 1 : 0);
00323     huffman_packer.u(8, start_value ? 1 : 0);
00324 
00325     // Code symbols both ways: raw vs. prefix
00326     for (const auto s : rle_symbols_) {
00327         raw_packer.u(8, s.symbol);
00328         huffman_encoders[s.state].write_symbol(huffman_packer, s.symbol);
00329     }
00330 
00331     return EncodedChunk(raw_packer.finish(), huffman_packer.finish());
00332 }
00333 
00334 EncodedChunk EntropyEncoderTemporal::process(const Surface &surface, unsigned transform_block_size, bool use_reduced_signalling) {
00335     auto view = surface.view_as<uint8_t>();
00336     const unsigned width = view.width();
00337     const unsigned height = view.height();
00338 
00339     EntropyModelRleFlag models;
00340 
00341     // Divisor for block->tiles
00342     const unsigned d = 32 / transform_block_size;
00343 
00344     // RLE state
00345     bool start = 0;
00346     bool value = 0;
00347     unsigned count = 0;
00348 
00349     bool has_entropy = false;
00350 
00351     // For each tile (including any part tiles) ...
00352     for (unsigned ty = 0; ty < height; ty += d) {
00353         for (unsigned tx = 0; tx < width; tx += d) {
00354 
00355             bool intra_tile = false;
00356 
00357             // For each transform in tile ...
00358             for (unsigned y = ty; y < std::min(ty + d, height); ++y) {
00359                 for (unsigned x = tx; x < std::min(tx + d, width); ++x) {
00360                     const bool first_transform_in_tile = (tx == x) && (ty == y);
00361                     const bool v = (view.read(x, y) == TemporalType::TEMPORAL_INTR) ? 1 : 0;
00362 
00363                     // Record if there is any data in surface
00364                     if (v)
00365                         has_entropy = true;
00366 
00367                     // Record intra flag for whole tile
00368                     if (use_reduced_signalling && first_transform_in_tile && v != 0)
00369                         intra_tile = true;
00370 
00371                     // Reduced signalling - don't encode rest of tile if first is intra
00372                     if (!first_transform_in_tile && use_reduced_signalling && intra_tile)
00373                         continue;
00374 
00375                     if (x == 0 && y == 0) {
00376                         // Special case - store first symbol
00377                         start = value = v;
00378                         count = 1;
00379                     } else if (v == value) {
00380                         // Extend run
00381                         ++count;
00382                     } else {
00383                         // Encode run
00384                         models.encode_run(value, count);
00385                         value = v;
00386                         count = 1;
00387                     }
00388                 }
00389             }
00390         }
00391     }
00392 
00393     // Emit last run
00394     models.encode_run(value, count);
00395 
00396     if (has_entropy)
00397         return models.finish(start);
00398     else
00399         return EncodedChunk();
00400 }
00401 
00402 EncodedChunk EntropyEncoderFlags::process(const Surface &surface) {
00403     auto view = surface.view_as<uint8_t>();
00404     const unsigned width = view.width();
00405     const unsigned height = view.height();
00406 
00407     EntropyModelRleFlag models;
00408 
00409     // RLE state
00410     bool start = 0;
00411     bool value = 0;
00412     unsigned count = 0;
00413 
00414     // For each flag ...
00415     for (unsigned y = 0; y < height; ++y) {
00416         for (unsigned x = 0; x < width; ++x) {
00417 
00418             const bool v = (view.read(x, y) != 0) ? true : false;
00419 
00420             if (x == 0 && y == 0) {
00421                 // Special case - store first symbol
00422                 start = value = v;
00423                 count = 1;
00424             } else if (v == value) {
00425                 // Extend run
00426                 ++count;
00427             } else {
00428                 // Encode run
00429                 models.encode_run(value, count);
00430                 value = v;
00431                 count = 1;
00432             }
00433         }
00434     }
00435 
00436     // Emit last run
00437     models.encode_run(value, count);
00438 
00439     return models.finish(start);
00440 }
