00443 //
00444 // Used for tile sizes
00445 //
00446 class EntropyModelSizes {
00447     // State of the size modelling - used to select between 2 huffman trees
00448     enum State { STATE_LSB, STATE_MSB, STATE_COUNT };
00449 
00450 public:
00451     EntropyModelSizes() {}
00452 
00453     void encode_size(uint16_t value);
00454     void encode_size_delta(int32_t value);
00455     EncodedChunk finish();
00456 
00457 private:
00458     void encode_symbol(State state, unsigned symbol);
00459 
00460     HuffmanEncoderBuilder huffman_state_[STATE_COUNT];
00461 
00462     struct RleSymbol {
00463         RleSymbol() = default;
00464         RleSymbol(State st, uint8_t sy) : state(st), symbol(sy) {}
00465         State state = STATE_LSB;
00466         uint8_t symbol = 0;
00467     };
00468 
00469     std::vector<RleSymbol> rle_symbols_;
00470 };
00471 
00472 void EntropyModelSizes::encode_symbol(State state, unsigned symbol) {
00473     rle_symbols_.emplace_back(state, symbol);
00474     huffman_state_[state].add_symbol(symbol, 1);
00475 }
00476 
00477 void EntropyModelSizes::encode_size(uint16_t value) {
00478     CHECK(value <= 32767);
00479 
00480     if (value < 0x80) {
00481         encode_symbol(STATE_LSB, (value * 2) | 0x00);
00482     } else {
00483         encode_symbol(STATE_LSB, ((value & 0x7f) * 2) | 0x01);
00484         encode_symbol(STATE_MSB, value >> 7);
00485     }
00486 }
00487 
00488 void EntropyModelSizes::encode_size_delta(int32_t value) {
00489     CHECK(value >= -16384 && value <= 16383);
00490 
00491     // Decoder will sign extend
00492     if (value >= -64 && value <= 63) {
00493         encode_symbol(STATE_LSB, ((value * 2) | 0x00) & 0xff);
00494     } else {
00495         encode_symbol(STATE_LSB, ((value & 0x7f) * 2) | 0x01);
00496         encode_symbol(STATE_MSB, (value >> 7) & 0xff);
00497     }
00498 }
00499 
00500 EncodedChunk EntropyModelSizes::finish() {
00501     // Generate huffman encoders
00502     std::vector<HuffmanEncoder> huffman_encoders;
00503 
00504     BitstreamPacker raw_packer;
00505     BitstreamPacker huffman_packer;
00506 
00507     // Finialise huffman encoders state
00508     for (unsigned h = 0; h < STATE_COUNT; ++h) {
00509         huffman_encoders.emplace_back(huffman_state_[h].finish());
00510         huffman_encoders.back().write_codes(huffman_packer);
00511     }
00512 
00513     // Code symbols both ways: raw vs. prefix
00514     for (const auto s : rle_symbols_) {
00515         raw_packer.u(8, s.symbol);
00516         huffman_encoders[s.state].write_symbol(huffman_packer, s.symbol);
00517     }
00518 
00519     return EncodedChunk(raw_packer.finish(), huffman_packer.finish());
00520 }
00521 
00522 EncodedChunk EntropyEncoderSizes::process(const Surface &surface, const std::vector<bool> entropy_enabled, const unsigned tile_idx,
00523                                           CompressionType compression_type) {
00524     auto view = surface.view_as<uint16_t>();
00525     const unsigned width = view.width();
00526     const unsigned height = view.height();
00527 
00528     EntropyModelSizes models;
00529 
00530     if (compression_type == CompressionType_Prefix) {
00531         for (unsigned y = 0; y < height; ++y) {
00532             for (unsigned x = 0; x < width; ++x) {
00533                 if (entropy_enabled[tile_idx + x]) {
00534                     const uint16_t v = view.read(x, y);
00535                     CHECK(v != 0);
00536                     models.encode_size(v);
00537                 }
00538             }
00539         }
00540     } else {
00541         uint16_t p = 0;
00542         for (unsigned y = 0; y < height; ++y) {
00543             for (unsigned x = 0; x < width; ++x) {
00544                 if (entropy_enabled[tile_idx + x]) {
00545                     const uint16_t v = view.read(x, y);
00546                     CHECK(v != 0);
00547                     models.encode_size_delta(v - p);
00548                     p = v;
00549                 }
00550             }
00551         }
00552     }
00553 
00554     return models.finish();
00555 }
